<?php require __DIR__ . '/../components/repository_header.php'; ?>
<div class="repository-body">
    <header class="detail-header"><span class="section-code">COMMIT RECORD / <?= e(strtoupper(short_sha($commit['sha']))) ?></span><h1><?= e($commit['subject']) ?></h1><div class="detail-meta"><span><b><?= e($commit['author_name']) ?></b> <?= t('authored this commit') ?></span><time><?= e(format_date($commit['author_date'])) ?></time><span class="commit-sha"><?= e($commit['sha']) ?></span></div><?php if (trim($commit['message']) !== $commit['subject']): ?><pre class="code-content"><?= e($commit['message']) ?></pre><?php endif; ?></header>
    <section class="diff-panel"><div class="diff-header"><span>PATCH / <?= e(short_sha($commit['sha'])) ?></span><span><?= count($commit['parents']) ?> <?= t('parent commits') ?></span></div><div class="diff-content"><?php foreach (explode("\n", $diff) as $line): ?><?php $class = str_starts_with($line, '+') && !str_starts_with($line, '+++') ? 'diff-add' : (str_starts_with($line, '-') && !str_starts_with($line, '---') ? 'diff-del' : (str_starts_with($line, '@@') || str_starts_with($line, 'diff ') ? 'diff-meta' : '')); ?><span class="diff-line <?= $class ?>"><?= e($line) ?: ' ' ?></span><?php endforeach; ?></div></section>
</div>
